+void Handler::updateBluetoothOff()
+{
+    const bool bluetoothOff = m_bluezManager->isInitialized() && !m_bluezManager->isBluetoothOperational()
+        && (m_bluezManager->isBluetoothBlocked() || !m_bluezManager->adapters().isEmpty());
+    if (m_bluetoothOff != bluetoothOff) {
+        m_bluetoothOff = bluetoothOff;
+        Q_EMIT bluetoothOffChanged();
+    }
+}
+
+QCoro::Task<QString> Handler::turnOnBluetoothForConnection(QString bluetoothAddress)
+{
+    if (m_bluezManager->isBluetoothBlocked()) {
+        m_bluezManager->setBluetoothBlocked(false);
+    }
+    for (const BluezQt::AdapterPtr &adapter : m_bluezManager->adapters()) {
+        if (!adapter->isPowered()) {
+            adapter->setPowered(true);
+        }
+    }
+
+    // NetworkManager adds the Bluetooth device once BlueZ reports the adapter as powered
+    QPointer<Handler> thisGuard(this);
+    const QDeadlineTimer deadline(std::chrono::seconds(15));
+    while (thisGuard && !deadline.hasExpired()) {
+        NetworkManager::Device::Ptr bluetoothDevice;
+        for (const NetworkManager::Device::Ptr &device : NetworkManager::networkInterfaces()) {
+            const auto btDevice = device.objectCast<NetworkManager::BluetoothDevice>();
+            if (btDevice && btDevice->hardwareAddress().compare(bluetoothAddress, Qt::CaseInsensitive) == 0) {
+                bluetoothDevice = device;
+                break;
+            }
+        }
+
+        const auto timeout = std::chrono::duration_cast<std::chrono::milliseconds>(deadline.remainingTimeAsDuration());
+        if (!bluetoothDevice) {
+            co_await qCoro(NetworkManager::notifier(), &NetworkManager::Notifier::deviceAdded, timeout);
+        } else if (bluetoothDevice->state() <= NetworkManager::Device::Unavailable) {
+            co_await qCoro(bluetoothDevice.data(), &NetworkManager::Device::stateChanged, timeout);
+        } else {
+            co_return bluetoothDevice->uni();
+        }
+    }
+    co_return QString();
+}
